// The official QoreSeal test vectors, run against the published npm package.
//
// Source: qorechain/qoreseal at commit bbd4dbbe8b987639be4f0b12084000e7da2272f4,
// file vectors/qoreseal-v1.json, copied unedited to
// fixtures/qoreseal-vectors-v1.json (SHA-256 recorded in the sidecar). The
// vector file is generated by the official TypeScript implementation and is
// checked by the Rust, Go, Swift, Kotlin and Python suites there, so a pass
// here means this repository's pinned build agrees with that wire format.
//
// This harness is our own; it is not a copy of the upstream test file. It
// covers the same sections: keys, primitives, envelopes, negative cases, the
// recipient card, the registry encodings, epoch keys and batches.

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { deriveCanonicalPqKey, deriveClassicalKey } from "@qorechain/qoresign";
import { describe, expect, it } from "vitest";
import * as qs from "@qorechain/qoreseal";
import { sealBatchWithEntropy, sealWithEntropy } from "@qorechain/qoreseal/testing";

const FIXTURES = fileURLToPath(new URL("../../../fixtures/", import.meta.url));

interface VectorKey {
  seed: string;
  mlkemPublicKey: string;
  mlkemSecretKeySha3: string;
  x25519PublicKey: string;
  x25519SecretKey: string;
}

interface VectorEnvelope {
  name: string;
  mode: "hybrid" | "mlkem";
  anonymous: boolean;
  recipients: number[];
  plaintext: string;
  aad: string;
  entropy: string;
  size: number;
  envelope: string;
  text: string;
}

interface VectorNegative {
  name: string;
  base: string;
  key: number;
  chainId?: string;
  purpose?: string;
  aad?: string;
  flip?: number;
  set?: [number, number];
  truncate?: number;
  error: string;
}

interface VectorCard {
  mnemonic: string;
  address: string;
  pqPublicKey: string;
  sealKeysIndex: number;
  text: string;
  card: qs.RecipientCard;
  negative: {
    name: string;
    chainId?: string;
    address?: string;
    mlkemKey?: number;
    x25519PublicKey?: string;
    error: string;
  }[];
}

interface Vectors {
  format: string;
  chainId: string;
  purpose: string;
  keys: VectorKey[];
  mnemonicSeeds: {
    mnemonic: string;
    passphrase: string;
    index: number;
    seed: string;
    mlkemPublicKeySha3: string;
  }[];
  encapsulation: { recipient: number; m: string; ciphertext: string; sharedSecret: string };
  x25519: {
    recipient: number;
    ephemeralSecretKey: string;
    ephemeralPublicKey: string;
    sharedSecret: string;
  };
  hybrid: {
    label: string;
    mlkemSharedSecret: string;
    x25519SharedSecret: string;
    x25519Ciphertext: string;
    x25519PublicKey: string;
    shared: string;
  };
  kdf: { shared: string; chainId: string; purpose: string; salt: string; info: string; key: string }[];
  hint: { salt: string; recipient: number; hint: string };
  envelopes: VectorEnvelope[];
  negative: VectorNegative[];
  textNegative: { name: string; text: string; error: string }[];
  card: VectorCard;
  registry: {
    sender: string;
    register: { typeUrl: string; value: string };
    remove: { typeUrl: string; value: string };
  };
  epoch: {
    purpose: string;
    epoch: number;
    key: string;
    payload: string;
    recipients: number[];
    entropy: string;
    envelope: string;
  };
  batch: {
    epoch: number;
    key: string;
    context: string;
    batchIndex: number;
    data: string;
    entropy: string;
    blob: string;
    ciphertextCommitment: string;
    plaintextCommitment: string;
  };
  sizes: { mode: "hybrid" | "mlkem"; recipients: number; plaintextLength: number; size: number }[];
}

const v = JSON.parse(
  readFileSync(join(FIXTURES, "qoreseal-vectors-v1.json"), "utf8"),
) as Vectors;

const hex = qs.toHex;
const unhex = qs.fromHex;
const keys = v.keys.map((k) => qs.sealKeysFromSeed(unhex(k.seed)));

/** The stable QoreSeal error code a call failed with, or "none" if it did not. */
function codeOf(fn: () => unknown): string {
  try {
    fn();
  } catch (err) {
    return (err as { code?: string }).code ?? "no code";
  }
  return "none";
}

describe("published QoreSeal vectors", () => {
  it("declares the expected format and chain", () => {
    expect(v.format).toBe("qoreseal-vectors-v1");
    expect(v.chainId).toBe("qorechain-diana");
  });

  describe("keys", () => {
    it("derives both key pairs from a seed", () => {
      v.keys.forEach((k, i) => {
        const pair = keys[i];
        expect(pair).toBeDefined();
        if (!pair) return;
        expect(hex(pair.mlkemPublicKey)).toBe(k.mlkemPublicKey);
        expect(hex(sha3(pair.mlkemSecretKey))).toBe(k.mlkemSecretKeySha3);
        expect(hex(pair.x25519PublicKey)).toBe(k.x25519PublicKey);
        expect(hex(pair.x25519SecretKey)).toBe(k.x25519SecretKey);
      });
    });

    it("derives seeds from a mnemonic", () => {
      for (const m of v.mnemonicSeeds) {
        const seed = qs.sealSeedFromMnemonic({
          mnemonic: m.mnemonic,
          passphrase: m.passphrase,
          index: m.index,
        });
        expect(hex(seed)).toBe(m.seed);
        expect(hex(sha3(qs.sealKeysFromSeed(seed).mlkemPublicKey))).toBe(m.mlkemPublicKeySha3);
      }
    });
  });

  describe("primitives", () => {
    it("encapsulates and decapsulates", () => {
      const e = v.encapsulation;
      const recipient = keys[e.recipient];
      expect(recipient).toBeDefined();
      if (!recipient) return;
      const out = qs.mlkemEncapsulate(recipient.mlkemPublicKey, unhex(e.m));
      expect(hex(out.cipherText)).toBe(e.ciphertext);
      expect(hex(out.sharedSecret)).toBe(e.sharedSecret);
      expect(hex(qs.mlkemDecapsulate(recipient.mlkemSecretKey, unhex(e.ciphertext)))).toBe(
        e.sharedSecret,
      );
    });

    it("agrees on X25519", () => {
      const x = v.x25519;
      const recipient = keys[x.recipient];
      expect(recipient).toBeDefined();
      if (!recipient) return;
      expect(hex(qs.x25519PublicKey(unhex(x.ephemeralSecretKey)))).toBe(x.ephemeralPublicKey);
      expect(hex(qs.x25519Agree(unhex(x.ephemeralSecretKey), recipient.x25519PublicKey))).toBe(
        x.sharedSecret,
      );
      expect(hex(qs.x25519Agree(recipient.x25519SecretKey, unhex(x.ephemeralPublicKey)))).toBe(
        x.sharedSecret,
      );
    });

    it("combines the hybrid secret", () => {
      const h = v.hybrid;
      expect(qs.HYBRID_LABEL).toBe(h.label);
      const shared = qs.hybridSharedSecret({
        mlkemSharedSecret: unhex(h.mlkemSharedSecret),
        x25519SharedSecret: unhex(h.x25519SharedSecret),
        x25519Ciphertext: unhex(h.x25519Ciphertext),
        x25519PublicKey: unhex(h.x25519PublicKey),
      });
      expect(hex(shared)).toBe(h.shared);
    });

    it("derives keys", () => {
      for (const k of v.kdf) {
        expect(qs.kdfInfo(k.chainId, k.purpose)).toBe(k.info);
        expect(
          hex(
            qs.deriveKey({
              shared: unhex(k.shared),
              chainId: k.chainId,
              purpose: k.purpose,
              salt: unhex(k.salt),
            }),
          ),
        ).toBe(k.key);
      }
    });

    it("computes the hint", () => {
      const recipient = keys[v.hint.recipient];
      expect(recipient).toBeDefined();
      if (!recipient) return;
      expect(hex(qs.recipientHint(unhex(v.hint.salt), recipient.mlkemPublicKey))).toBe(v.hint.hint);
    });
  });

  describe("envelopes", () => {
    for (const e of v.envelopes) {
      it(`${e.name}: seals byte for byte and opens for every recipient`, () => {
        const env = sealWithEntropy(
          {
            chainId: v.chainId,
            purpose: v.purpose,
            mode: e.mode,
            anonymous: e.anonymous,
            recipients: e.recipients.map((i) => {
              const pair = keys[i];
              if (!pair) throw new Error(`vector names recipient ${i}`);
              return qs.recipientOf(pair);
            }),
            plaintext: unhex(e.plaintext),
            aad: unhex(e.aad),
          },
          unhex(e.entropy),
        );
        expect(hex(env)).toBe(e.envelope);
        expect(env.length).toBe(e.size);
        expect(qs.envelopeToText(env)).toBe(e.text);
        expect(hex(qs.envelopeFromText(e.text))).toBe(e.envelope);
        for (const i of e.recipients) {
          const pair = keys[i];
          if (!pair) throw new Error(`vector names recipient ${i}`);
          expect(
            hex(qs.open({ chainId: v.chainId, purpose: v.purpose, envelope: env, keys: pair, aad: unhex(e.aad) })),
          ).toBe(e.plaintext);
        }
        const parsed = qs.parseEnvelope(env);
        expect(parsed.mode).toBe(e.mode);
        expect(parsed.anonymous).toBe(e.anonymous);
        expect(parsed.entries.length).toBe(e.recipients.length);
      });
    }

    it("reports the expected error for every negative case", () => {
      const byName = new Map(v.envelopes.map((e) => [e.name, e]));
      for (const n of v.negative) {
        const base = byName.get(n.base);
        if (!base) throw new Error(`negative case ${n.name} names base ${n.base}`);
        const pair = keys[n.key];
        if (!pair) throw new Error(`negative case ${n.name} names key ${n.key}`);
        let env = Uint8Array.from(unhex(base.envelope));
        if (n.flip !== undefined) env[n.flip] = (env[n.flip] ?? 0) ^ 0x01;
        if (n.set) {
          const [index, value] = n.set;
          env[index] = value;
        }
        if (n.truncate !== undefined) env = env.slice(0, n.truncate);
        const code = codeOf(() =>
          qs.open({
            chainId: n.chainId ?? v.chainId,
            purpose: n.purpose ?? v.purpose,
            envelope: env,
            keys: pair,
            aad: unhex(n.aad ?? base.aad),
          }),
        );
        expect(code, n.name).toBe(n.error);
      }
      for (const t of v.textNegative) {
        expect(codeOf(() => qs.envelopeFromText(t.text)), t.name).toBe(t.error);
      }
    });

    it("matches the size table", () => {
      for (const s of v.sizes) expect(qs.envelopeSize(s)).toBe(s.size);
    });
  });

  describe("recipient card", () => {
    const c = v.card;
    const classical = deriveClassicalKey({ mnemonic: c.mnemonic });
    const pq = deriveCanonicalPqKey({ mnemonic: c.mnemonic, address: c.address });
    const sealKeys = qs.deriveSealKeys({ mnemonic: c.mnemonic, index: c.sealKeysIndex });

    it("signs the card byte for byte", () => {
      expect(hex(pq.publicKey)).toBe(c.pqPublicKey);
      const card = qs.signRecipientCard({
        chainId: v.chainId,
        address: c.address,
        keys: sealKeys,
        classicalKey: classical,
        pqKey: pq,
        issuedAt: c.card.issuedAt,
      });
      expect(qs.recipientCardText(card)).toBe(c.text);
      expect(card).toEqual(c.card);
    });

    it("verifies the card against the keys on chain", () => {
      const r = qs.verifyRecipientCard({
        card: c.card,
        chainId: v.chainId,
        address: c.address,
        pqPublicKey: unhex(c.pqPublicKey),
        mlkemPublicKey: sealKeys.mlkemPublicKey,
      });
      expect(r.x25519PublicKey && hex(r.x25519PublicKey)).toBe(hex(sealKeys.x25519PublicKey));
    });

    it("refuses the negative cases", () => {
      for (const n of c.negative) {
        const card = {
          ...c.card,
          ...(n.x25519PublicKey ? { x25519PublicKey: n.x25519PublicKey } : {}),
        };
        const other = n.mlkemKey !== undefined ? keys[n.mlkemKey] : undefined;
        const code = codeOf(() =>
          qs.verifyRecipientCard({
            card,
            chainId: n.chainId ?? v.chainId,
            address: n.address ?? c.address,
            pqPublicKey: unhex(c.pqPublicKey),
            mlkemPublicKey: other ? other.mlkemPublicKey : sealKeys.mlkemPublicKey,
          }),
        );
        expect(code, n.name).toBe(n.error);
      }
    });
  });

  describe("registry, epochs and batches", () => {
    it("encodes the registry messages", () => {
      const r = v.registry;
      const sealKeys = qs.deriveSealKeys({ mnemonic: v.card.mnemonic });
      const reg = qs.buildRegisterKemKeyMessage({
        sender: r.sender,
        mlkemPublicKey: sealKeys.mlkemPublicKey,
      });
      expect(reg.typeUrl).toBe(r.register.typeUrl);
      expect(hex(reg.value)).toBe(r.register.value);
      const rem = qs.buildRemoveKemKeyMessage({ sender: r.sender });
      expect(rem.typeUrl).toBe(r.remove.typeUrl);
      expect(hex(rem.value)).toBe(r.remove.value);
    });

    it("seals and opens the epoch key", () => {
      const e = v.epoch;
      const epochKey = { epoch: BigInt(e.epoch), key: unhex(e.key) };
      expect(hex(qs.encodeEpochKey(epochKey))).toBe(e.payload);
      const env = sealWithEntropy(
        {
          chainId: v.chainId,
          purpose: e.purpose,
          recipients: e.recipients.map((i) => {
            const pair = keys[i];
            if (!pair) throw new Error(`vector names recipient ${i}`);
            return qs.recipientOf(pair);
          }),
          plaintext: qs.encodeEpochKey(epochKey),
        },
        unhex(e.entropy),
      );
      expect(hex(env)).toBe(e.envelope);
      for (const i of e.recipients) {
        const pair = keys[i];
        if (!pair) throw new Error(`vector names recipient ${i}`);
        const got = qs.openEpochKey({
          chainId: v.chainId,
          purpose: e.purpose,
          envelope: env,
          keys: pair,
        });
        expect(got.epoch).toBe(1n);
        expect(hex(got.key)).toBe(e.key);
      }
    });

    it("seals and opens the batch", () => {
      const b = v.batch;
      const epochKey = { epoch: BigInt(b.epoch), key: unhex(b.key) };
      const sealed = sealBatchWithEntropy(
        {
          epochKey,
          context: b.context,
          batchIndex: BigInt(b.batchIndex),
          data: unhex(b.data),
        },
        unhex(b.entropy),
      );
      expect(hex(sealed.blob)).toBe(b.blob);
      expect(hex(sealed.ciphertextCommitment)).toBe(b.ciphertextCommitment);
      expect(hex(sealed.plaintextCommitment)).toBe(b.plaintextCommitment);
      const opened = qs.openBatch({ blob: sealed.blob, keys: [epochKey] });
      expect(hex(opened.data)).toBe(b.data);
      expect(opened.batchIndex).toBe(7n);
      expect(opened.context).toBe(b.context);
      expect(hex(opened.plaintextCommitment)).toBe(b.plaintextCommitment);
      expect(sealed.blob.length).toBe(qs.batchSize(b.context.length, unhex(b.data).length));
    });
  });
});


function sha3(data: Uint8Array): Uint8Array {
  return new Uint8Array(createHash("sha3-256").update(data).digest());
}
